window.__finlexDocLoaded(185,{"id":185,"articles":[{"id":4614,"no":"第一条","heading":"","text":"为了规范注册会计师在财务报表审计中对期后事项的责任，制定本准则。对于与注册会计师在审计报告日后获取的其他信息的责任相关的事项，本准则不予规范，而是由《中国注册会计师审计准则第1521号——注册会计师对其他信息的责任》作出规范。然而，这种其他信息可能揭示出本准则范围内的期后事项。","seq":0,"links":[{"doc_id":194,"tier":"L3","score":64,"rel_kind":"cites","target_seq":10,"target_art_no":"第十一条","dir":"in","note":"正文显式引用《中国注册会计师审计准则第1332号——期后事项（2016年12月23日修订）》"},{"doc_id":199,"tier":"L3","score":64,"rel_kind":"cites","target_seq":14,"target_art_no":"第十五条","dir":"in","note":"正文显式引用《中国注册会计师审计准则第1332号——期后事项（2016年12月23日修订）》"}]},{"id":4615,"no":"第二条","heading":"","text":"财务报表可能受到财务报表日后发生的事项的影响。适用的财务报告编制基础通常专门提及期后事项，将其区分为下列两类： **（一）对财务报表日已经存在的情况提供证据的事项；** **（二）对财务报表日后发生的情况提供证据的事项。** 审计报告的日期向财务报表使用者表明，注册会计师已考虑其知悉的、截至审计报告日发生的事项和交易的影响。 ## 第二章 定义","seq":1},{"id":4616,"no":"第三条","heading":"","text":"期后事项，是指财务报表日至审计报告日之间发生的事项，以及注册会计师在审计报告日后知悉的事实。","seq":2},{"id":4617,"no":"第四条","heading":"","text":"财务报表日，是指财务报表涵盖的最近期间的截止日期。","seq":3},{"id":4618,"no":"第五条","heading":"","text":"审计报告日，是指注册会计师按照《中国注册会计师审计准则第1501号——对财务报表形成审计意见和出具审计报告》的规定在对财务报表出具的审计报告上签署的日期。","seq":4,"links":[{"doc_id":190,"tier":"L3","score":64,"rel_kind":"cites","target_seq":0,"target_art_no":"第一条","dir":"out","note":"正文显式引用《中国注册会计师审计准则第1501号——对财务报表形成审计意见和出具审计报告（2022年12月22日修订）》"}]},{"id":4619,"no":"第六条","heading":"","text":"财务报表报出日，是指审计报告和已审计财务报表提供给第三方的日期。","seq":5},{"id":4620,"no":"第七条","heading":"","text":"财务报表批准日，是指构成整套财务报表的所有报表（包括相关附注）已编制完成，并且被审计单位的董事会、管理层或类似机构已经认可其对财务报表负责的日期。 ## 第三章 目标","seq":6},{"id":4621,"no":"第八条","heading":"","text":"注册会计师的目标是： （一）获取充分、适当的审计证据，以确定财务报表日至审计报告日之间发生的、需要在财务报表中调整或披露的事项是否已经按照适用的财务报告编制基础在财务报表中得到恰当反映； （二）恰当应对在审计报告日后注册会计师知悉的、且如果在审计报告日知悉可能导致注册会计师修改审计报告的事实。 ## 第四章 要求 ### 第一节 财务报表日至审计报告日之间发生的事项","seq":7},{"id":4622,"no":"第九条","heading":"","text":"注册会计师应当设计和实施审计程序，获取充分、适当的审计证据，以确定所有在财务报表日至审计报告日之间发生的、需要在财务报表中调整或披露的事项均已得到识别。但是，注册会计师并不需要对之前已实施审计程序并已得出满意结论的事项执行追加的审计程序。","seq":8},{"id":4623,"no":"第十条","heading":"","text":"注册会计师应当按照本准则第九条的规定实施审计程序，以使审计程序能够涵盖财务报表日至审计报告日（或尽可能接近审计报告日）之间的期间。在确定审计程序的性质和范围时，注册会计师应当考虑风险评估的结果。这些程序应当包括： **（一）了解管理层为确保识别期后事项而建立的程序；** （二）询问管理层和治理层（如适用），确定是否已发生可能影响财务报表的期后事项； （三）查阅被审计单位的所有者、管理层和治理层在财务报表日后举行会议的纪要，在不能获取会议纪要的情况下，询问此类会议讨论的事项； **（四）查阅被审计单位最近的中期财务报表（如有）。**","seq":9,"links":[{"doc_id":167,"tier":"L3","score":72,"rel_kind":"cites","target_seq":23,"target_art_no":"第二十四条","dir":"in","note":"正文显式引用《中国注册会计师审计准则第1332号——期后事项（2016年12月23日修订）》第10条"}]},{"id":4624,"no":"第十一条","heading":"","text":"在实施本准则第九条和第十条规定的审计程序后，如果注册会计师识别出需要在财务报表中调整或披露的事项，应当确定这些事项是否按照适用的财务报告编制基础的规定在财务报表中得到恰当反映。","seq":10},{"id":4625,"no":"第十二条","heading":"","text":"注册会计师应当按照《中国注册会计师审计准则第1341号——书面声明》的规定，要求管理层和治理层（如适用）提供书面声明，确认所有在财务报表日后发生的、按照适用的财务报告编制基础的规定应予调整或披露的事项均已得到调整或披露。 ### 第二节 注册会计师在审计报告日后至财务报表报出日前知悉的事实","seq":11,"links":[{"doc_id":186,"tier":"L3","score":72,"rel_kind":"cites","target_seq":18,"target_art_no":"第十九条","dir":"in","note":"正文显式引用《中国注册会计师审计准则第1332号——期后事项（2016年12月23日修订）》第12条"},{"doc_id":186,"tier":"L3","score":64,"rel_kind":"cites","target_seq":0,"target_art_no":"第一条","dir":"out","note":"正文显式引用《中国注册会计师审计准则第1341号——书面声明（2022年12月22日修订）》"}]},{"id":4626,"no":"第十三条","heading":"","text":"在审计报告日后，注册会计师没有义务针对财务报表实施任何审计程序。在审计报告日后至财务报表报出日前，如果知悉了某事实，且若在审计报告日知悉可能导致修改审计报告，注册会计师应当： **（一）与管理层和治理层（如适用）讨论该事项；** **（二）确定财务报表是否需要修改；** **（三）如果需要修改，询问管理层将如何在财务报表中处理该事项。**","seq":12},{"id":4627,"no":"第十四条","heading":"","text":"如果管理层修改财务报表，注册会计师应当： **（一）根据具体情况对有关修改实施必要的审计程序；** （二）除非本准则第十五条所述的情形适用，将本准则第九条和第十条规定的审计程序延伸至新的审计报告日，并针对修改后的财务报表出具新的审计报告。新的审计报告日不应早于修改后的财务报表被批准的日期。","seq":13},{"id":4628,"no":"第十五条","heading":"","text":"在有关法律法规或适用的财务报告编制基础未禁止的情况下，如果管理层对财务报表的修改仅限于反映导致修改的期后事项的影响，被审计单位的董事会、管理层或类似机构也仅对有关修改进行批准，注册会计师可以仅针对有关修改将本准则第九条和第十条所述的审计程序延伸至新的审计报告日。在这种情况下，注册会计师应当选用下列处理方式之一： （一）修改审计报告，针对财务报表修改部分增加补充报告日期，从而表明注册会计师对期后事项实施的审计程序仅限于财务报表相关附注所述的修改； （二）出具新的或经修改的审计报告，在强调事项段或其他事项段中说明注册会计师对期后事项实施的审计程序仅限于财务报表相关附注所述的修改。","seq":14,"links":[{"doc_id":192,"tier":"L3","score":72,"rel_kind":"cites","target_seq":12,"target_art_no":"第十三条","dir":"in","note":"正文显式引用《中国注册会计师审计准则第1332号——期后事项（2016年12月23日修订）》第15条"}]},{"id":4629,"no":"第十六条","heading":"","text":"在某些国家或地区，法律法规或财务报告编制基础可能不要求管理层报出经修改的财务报表，相应地，注册会计师也无需出具经修改的或新的审计报告。然而，如果认为管理层应当修改财务报表而没有修改，注册会计师应当分别以下情况予以处理： （一）如果审计报告尚未提交给被审计单位，注册会计师应当按照《中国注册会计师审计准则第1502号——在审计报告中发表非无保留意见》的规定发表非无保留意见，然后再提交审计报告； （二）如果审计报告已经提交给被审计单位，注册会计师应当通知管理层和治理层（除非治理层全部成员参与管理被审计单位）在财务报表作出必要修改前不要向第三方报出。如果财务报表在未经必要修改的情况下仍被报出，注册会计师应当采取适当措施，以设法防止财务报表使用者信赖该审计报告。 ### 第三节 注册会计师在财务报表报出后知悉的事实","seq":15,"links":[{"doc_id":191,"tier":"L3","score":64,"rel_kind":"cites","target_seq":0,"target_art_no":"第一条","dir":"out","note":"正文显式引用《中国注册会计师审计准则第1502号——在审计报告中发表非无保留意见（2019年2月20日修订）》"}]},{"id":4630,"no":"第十七条","heading":"","text":"在财务报表报出后，注册会计师没有义务针对财务报表实施任何审计程序。在财务报表报出后，如果知悉了某事实，且若在审计报告日知悉可能导致修改审计报告，注册会计师应当： **（一）与管理层和治理层（如适用）讨论该事项；** **（二）确定财务报表是否需要修改；** **（三）如果需要修改，询问管理层将如何在财务报表中处理该事项。**","seq":16},{"id":4631,"no":"第十八条","heading":"","text":"如果管理层修改了财务报表，注册会计师应当： **（一）根据具体情况对有关修改实施必要的审计程序；** （二）复核管理层采取的措施能否确保所有收到原财务报表和审计报告的人士了解这一情况； （三）除非本准则第十五条所述的情形适用，将本准则第九条和第十条规定的审计程序延伸至新的审计报告日，并针对修改后的财务报表出具新的审计报告，新的审计报告日不应早于修改后的财务报表被批准的日期； （四）如果本准则第十五条所述的情形适用，应当按照本准则第十五条的规定修改审计报告或提供新的审计报告。","seq":17},{"id":4632,"no":"第十九条","heading":"","text":"注册会计师应当在新的或经修改的审计报告中增加强调事项段或其他事项段，提醒财务报表使用者关注财务报表附注中有关修改原财务报表的详细原因和注册会计师提供的原审计报告。","seq":18},{"id":4633,"no":"第二十条","heading":"","text":"如果管理层没有采取必要措施确保所有收到原财务报表的人士了解这一情况，也没有在注册会计师认为需要修改的情况下修改财务报表，注册会计师应当通知管理层和治理层（除非治理层全部成员参与管理被审计单位），注册会计师将设法防止财务报表使用者信赖该审计报告。如果注册会计师已经通知管理层或治理层，而管理层或治理层没有采取必要措施，注册会计师应当采取适当措施，以设法防止财务报表使用者信赖该审计报告。","seq":19}]});
